    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="4" y="7.5" width="16" height="12" rx="1" /><path d="M7 7.5 L7 4.5 L17 4.5 L17 7.5 M7 13.5 L17 13.5" /><circle cx="12" cy="16.5" r="0.8" />
